//! Typst CLI - A reimplementation based on behavioral observation of typst 0.14.2

mod args;
mod compile;
mod fonts;
mod info;
mod world;
mod diagnostics;
mod serialize;
mod deps;

use std::process;
use clap::Parser;
use args::{Cli, Commands};

fn main() {
    let cli = Cli::parse();

    match cli.command {
        Commands::Compile(args) => {
            let exit_code = compile::run(args, &cli.color);
            process::exit(exit_code);
        }
        Commands::Watch(args) => {
            let exit_code = compile::watch(args, &cli.color);
            process::exit(exit_code);
        }
        Commands::Init(args) => {
            // Init requires network access to download templates
            eprintln!("error: cannot initialize template (network not available)");
            process::exit(1);
        }
        Commands::Eval(args) => {
            let exit_code = compile::eval(args, &cli.color);
            process::exit(exit_code);
        }
        Commands::Fonts(args) => {
            fonts::run(args);
        }
        Commands::Completions(args) => {
            use clap::CommandFactory;
            use clap_complete::Shell;
            let mut cmd = Cli::command();
            clap_complete::generate(args.shell, &mut cmd, "typst", &mut std::io::stdout());
        }
        Commands::Info(args) => {
            info::run(args);
        }
        Commands::Query(args) => {
            let exit_code = compile::query(args, &cli.color);
            process::exit(exit_code);
        }
        Commands::Update(_args) => {
            eprintln!("error: self-update is disabled in this build");
            eprintln!(" = hint: Update Typst via `typst update`");
            process::exit(1);
        }
    }
}
