//! CLI argument definitions for typst

use std::path::PathBuf;
use clap::{Parser, Subcommand, ValueEnum};
use clap_complete::Shell;

const VERSION: &str = "0.14.2";
const SHORT_HASH: &str = "ccc34be7";

fn version_string() -> String {
    format!("typst {} ({})", VERSION, SHORT_HASH)
}

#[derive(Parser, Debug)]
#[command(
    name = "typst",
    version = version_string(),
    long_version = version_string(),
    about = format!("Typst {} ({})\n", VERSION, SHORT_HASH),
    disable_help_subcommand = false,
    arg_required_else_help = true,
    after_help = "Resources:\n  Tutorial:                 https://typst.app/docs/tutorial/\n  Reference documentation:  https://typst.app/docs/reference/\n  Templates & Packages:     https://typst.app/universe/\n  Forum for questions:      https://forum.typst.app/",
)]
pub struct Cli {
    #[command(subcommand)]
    pub command: Commands,

    /// Whether to use color. When set to `auto` if the terminal to supports it
    #[arg(
        long,
        value_enum,
        global = true,
        default_value = "auto",
        value_name = "COLOR"
    )]
    pub color: ColorChoice,

    /// Path to a custom CA certificate to use when making network requests
    #[arg(long, env = "TYPST_CERT", global = true, value_name = "CERT")]
    pub cert: Option<PathBuf>,
}

#[derive(ValueEnum, Clone, Debug, PartialEq)]
pub enum ColorChoice {
    Auto,
    Always,
    Never,
}

#[derive(Subcommand, Debug)]
pub enum Commands {
    /// Compiles an input file into a supported output format
    #[command(alias = "c")]
    Compile(CompileArgs),

    /// Watches an input file and recompiles on changes
    #[command(alias = "w")]
    Watch(WatchArgs),

    /// Initializes a new project from a template
    Init(InitArgs),

    /// Evaluates a piece of Typst code, optionally in the context of a document
    Eval(EvalArgs),

    /// Lists all discovered fonts in system and custom font paths
    Fonts(FontsArgs),

    /// Generates shell completion scripts
    Completions(CompletionsArgs),

    /// Displays debugging information about Typst
    Info(InfoArgs),

    /// Processes an input file to extract provided metadata (deprecated, use `eval` instead)
    Query(QueryArgs),

    /// Self update the Typst CLI
    Update(UpdateArgs),
}

#[derive(clap::Args, Debug)]
pub struct CompileArgs {
    /// Path to input Typst file. Use `-` to read input from stdin
    #[arg(value_name = "INPUT")]
    pub input: String,

    /// Path to output file (PDF, PNG, SVG, or HTML). Use `-` to write output to stdout.
    ///
    /// For output formats emitting one file per page (PNG & SVG), a page
    /// number template must be present if the source document renders to
    /// multiple pages. Use `{p}` for page numbers, `{0p}` for zero padded
    /// page numbers and `{t}` for page count. For example,
    /// `page-{0p}-of-{t}.png` creates `page-01-of-10.png`,
    /// `page-02-of-10.png`, and so on.
    #[arg(value_name = "OUTPUT")]
    pub output: Option<String>,

    /// The format of the output file, inferred from the extension by default
    #[arg(short = 'f', long, value_name = "FORMAT")]
    pub format: Option<OutputFormat>,

    #[command(flatten)]
    pub world: WorldArgs,

    /// Which pages to export. When unspecified, all pages are exported.
    ///
    /// Pages to export are separated by commas, and can be either simple page
    /// numbers (e.g. '2,5' to export only pages 2 and 5) or page ranges (e.g.
    /// '2,3-6,8-' to export page 2, pages 3 to 6 (inclusive), page 8 and any
    /// pages after it).
    ///
    /// Page numbers are one-indexed and correspond to physical page numbers
    /// in the document (therefore not being affected by the document's page
    /// counter).
    #[arg(long, value_name = "PAGES")]
    pub pages: Option<String>,

    /// One (or multiple comma-separated) PDF standards that Typst will
    /// enforce conformance with
    #[arg(long, value_name = "PDF_STANDARD", value_delimiter = ',')]
    pub pdf_standard: Vec<PdfStandard>,

    /// By default, even when not producing a `PDF/UA-1` document, a tagged
    /// PDF document is written to provide a baseline of accessibility. In
    /// some circumstances (for example when trying to reduce the size of a
    /// document) it can be desirable to disable tagged PDF
    #[arg(long)]
    pub no_pdf_tags: bool,

    /// The PPI (pixels per inch) to use for PNG export
    #[arg(long, default_value = "144", value_name = "PPI")]
    pub ppi: f64,

    /// File path to which a list of current compilation's dependencies will
    /// be written. Use `-` to write to stdout
    #[arg(long, value_name = "PATH")]
    pub deps: Option<String>,

    /// File format to use for dependencies
    #[arg(long, default_value = "json", value_name = "DEPS_FORMAT")]
    pub deps_format: DepsFormat,

    /// Opens the output file with the default viewer or a specific program
    /// after compilation. Ignored if output is stdout
    #[arg(long, value_name = "VIEWER", num_args = 0..=1)]
    pub open: Option<Option<String>>,

    /// Produces performance timings of the compilation process.
    /// (experimental)
    ///
    /// The resulting JSON file can be loaded into a tracing tool such as
    /// https://ui.perfetto.dev. It does not contain any sensitive information
    /// apart from file names and line numbers.
    #[arg(long, value_name = "OUTPUT_JSON", num_args = 0..=1)]
    pub timings: Option<Option<String>>,
}

