                .unwrap_or_else(|| std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
            let main = FileId::new(None, VirtualPath::new("/-"));
            (root, main)
        } else {
            let input_path = PathBuf::from(input);
            let input_path = if input_path.is_absolute() {
                input_path
            } else {
                std::env::current_dir().unwrap().join(input_path)
            };

            // Canonicalize to handle .. etc.
            let canon = input_path.canonicalize()
                .unwrap_or_else(|_| input_path.clone());

            let root = if let Some(root) = &args.root {
                root.clone()
            } else {
                canon.parent().unwrap_or(Path::new(".")).to_path_buf()
            };

            let main = FileId::new(None, VirtualPath::new(
                canon.strip_prefix(&root).unwrap_or(&canon)
            ));

            (root, main)
        };

        // Build inputs dict
        let mut inputs = Dict::new();
        for input_str in &args.input {
            if let Some((k, v)) = input_str.split_once('=') {
                inputs.insert(k.into(), v.into_value());
            }
        }

        // Set up font searcher
        let mut searcher = FontSearcher::new();

        if !args.ignore_embedded_fonts {
            searcher.add_embedded();
        }

        if !args.ignore_system_fonts {
            searcher.search_system();
        }

        for path in &args.font_path {
            searcher.search_path(path);
        }

        let fonts = searcher.into_fonts();
        let book = Arc::new(FontBook::from_fonts(&fonts.iter().map(|f| f.font()).flatten().collect::<Vec<_>>()));

        // Set up package storage
        let package_storage = PackageStorage::new(
            args.package_cache_path.clone(),
            args.package_path.clone(),
            None,
        );

        Ok(Self {
            root,
            library: OnceLock::new(),
            book,
            fonts,
            source: OnceLock::new(),
            main,
            inputs,
            package_storage,
            sources: Mutex::new(HashMap::new()),
            files: Mutex::new(HashMap::new()),
            now: OnceLock::new(),
            creation_timestamp,
        })
    }

    pub fn root(&self) -> &Path {
        &self.root
    }

    pub fn main_id(&self) -> FileId {
        self.main
    }

    pub fn set_main_source(&self, source: Source) {
        let _ = self.source.set(source);
    }

    fn path_for_id(&self, id: FileId) -> FileResult<PathBuf> {
        if let Some(spec) = id.package() {
            // Package file
            let package_path = self.package_storage.prepare_package(spec)
                .map_err(|e| FileError::Other(Some(e.to_string().into())))?;
            Ok(package_path.join(id.vpath().as_rooted_path()))
        } else {
            // Local file
            let vpath = id.vpath();
            Ok(self.root.join(vpath.as_rooted_path()))
        }
    }
}

impl World for SystemWorld {
    fn library(&self) -> &Library {
        self.library.get_or_init(|| {
            let mut lib = Library::builder()
                .with_inputs(self.inputs.clone())
                .build();
            lib
        })
    }

    fn book(&self) -> &FontBook {
        &self.book
    }

    fn main(&self) -> FileId {
        self.main
    }

    fn source(&self, id: FileId) -> FileResult<Source> {
        if id == self.main {
            if let Some(src) = self.source.get() {
                return Ok(src.clone());
            }
        }

        let mut sources = self.sources.lock().unwrap();
        if let Some(result) = sources.get(&id) {
            return result.clone();
        }

        let result = self.read_source(id);
        sources.insert(id, result.clone());
        result
    }

    fn file(&self, id: FileId) -> FileResult<Arc<[u8]>> {
        let mut files = self.files.lock().unwrap();
        if let Some(result) = files.get(&id) {
            return result.clone().map(|v| v.into());
        }

        let result = self.read_file(id);
        files.insert(id, result.clone().map(|a: Arc<[u8]>| a.to_vec()));
        result
    }

    fn font(&self, index: usize) -> Option<Font> {
        self.fonts.get(index)?.font()
    }

    fn today(&self, offset: Option<i64>) -> Option<Datetime> {
        let now = self.now.get_or_init(|| {
            if let Some(ts) = self.creation_timestamp {
                let dt = Utc.timestamp_opt(ts, 0).single()?;
                let date = dt.date_naive();
                Datetime::from_ymd(
                    date.year(),
                    date.month() as u8,
                    date.day() as u8,
                )
            } else {
                let local = Local::now();
                Datetime::from_ymd(
                    local.year(),
                    local.month() as u8,
                    local.day() as u8,
                )
            }
        });

        now.as_ref().copied().map(|dt| {
            if let Some(off) = offset {
                // Apply offset... this is simplified
                dt
            } else {
                dt
            }
        })
    }
}

impl SystemWorld {
    fn read_source(&self, id: FileId) -> FileResult<Source> {
        let path = self.path_for_id(id)?;
        let bytes = std::fs::read(&path).map_err(|e| match e.kind() {
            std::io::ErrorKind::NotFound => FileError::NotFound(path.clone()),
            std::io::ErrorKind::PermissionDenied => FileError::AccessDenied,
            _ => FileError::Other(Some(e.to_string().into())),
        })?;
        let text = String::from_utf8(bytes)
            .map_err(|_| FileError::InvalidUtf8)?;
        Ok(Source::new(id, text))
    }

    fn read_file(&self, id: FileId) -> FileResult<Arc<[u8]>> {
        let path = self.path_for_id(id)?;
        let bytes = std::fs::read(&path).map_err(|e| match e.kind() {
            std::io::ErrorKind::NotFound => FileError::NotFound(path.clone()),
            std::io::ErrorKind::PermissionDenied => FileError::AccessDenied,
            _ => FileError::Other(Some(e.to_string().into())),
        })?;
        Ok(bytes.into())
    }
}
