        world.source(id).ok().map(|src| (id, src))
    }) {
        let (id, src) = span;
        let range = diag.span.range(&src).unwrap_or_default();
        let line = src.byte_to_line(range.start).unwrap_or(0) + 1;
        let col = src.byte_to_column(range.start).unwrap_or(0) + 1;

        // Get the file path
        let path = get_path_for_id(id, world);
        let _ = writeln!(handle, "{}:{}:{}: {}: {}", path, line, col, severity_str(&diag.severity), msg);
    } else {
        let _ = writeln!(handle, "{}: {}", severity_str(&diag.severity), msg);
    }

    for hint in &diag.hints {
        let _ = writeln!(handle, " = hint: {}", hint);
    }
}

fn print_human_diagnostic(
    diag: &SourceDiagnostic,
    world: &impl typst::World,
    handle: &mut impl Write,
    color: bool,
) {
    let msg = diag.message.as_str();
    let sev = severity_str(&diag.severity);

    if let Some(id) = diag.span.id() {
        if let Ok(src) = world.source(id) {
            let range = match diag.span.range(&src) {
                Some(r) => r,
                None => {
                    let _ = writeln!(handle, "{}: {}", sev, msg);
                    return;
                }
            };

            let line_num = src.byte_to_line(range.start).unwrap_or(0) + 1;
            let col_num = src.byte_to_column(range.start).unwrap_or(0) + 1;
            let path = get_path_for_id(id, world);

            let _ = writeln!(handle, "{}: {}", sev, msg);
            let _ = writeln!(handle, "  ┌─ {}:{}:{}", path, line_num, col_num);
            let _ = writeln!(handle, "  │");

            // Show source lines
            let line_start = src.byte_to_line(range.start).unwrap_or(0);
            let line_end = src.byte_to_line(range.end.saturating_sub(1)).unwrap_or(line_start);

            for line_idx in line_start..=line_end {
                let line_text = src.line(line_idx).unwrap_or("");
                let line_no = line_idx + 1;
                let _ = writeln!(handle, "{} │ {}", line_no, line_text);

                // Show underline
                let line_byte_start = src.line_to_byte(line_idx).unwrap_or(0);
                let underline_start = if line_idx == line_start {
                    range.start - line_byte_start
                } else {
                    0
                };
                let underline_end = if line_idx == line_end {
                    range.end - line_byte_start
                } else {
                    line_text.len()
                };

                let spaces: String = " ".repeat(format!("{}", line_no).len() + 2 + underline_start);
                let underline: String = "^".repeat(underline_end.saturating_sub(underline_start).max(1));
                let _ = writeln!(handle, "  │ {}{}", spaces, underline);
            }

            let _ = writeln!(handle, "");

            for hint in &diag.hints {
                let _ = writeln!(handle, " = hint: {}", hint);
            }

            return;
        }
    }

    let _ = writeln!(handle, "{}: {}", sev, msg);
    for hint in &diag.hints {
        let _ = writeln!(handle, " = hint: {}", hint);
    }
}

fn get_path_for_id(id: typst::syntax::FileId, world: &impl typst::World) -> String {
    // Try to get the path for this file
    let vpath = id.vpath();
    if let Some(pkg) = id.package() {
        format!("{}{}", pkg, vpath.as_rooted_path().display())
    } else {
        // Relative path from current directory
        let path = vpath.as_rooted_path();
        // Make it relative-looking
        format!("..{}", path.display())
    }
}
