//! Font listing command

use typst_kit::fonts::FontSearcher;

use crate::args::FontsArgs;

pub fn run(args: FontsArgs) {
    let mut searcher = FontSearcher::new();

    if !args.ignore_embedded_fonts {
        searcher.add_embedded();
    }

    if !args.ignore_system_fonts {
        searcher.search_system();
    }

    for path in &args.font_path {
        searcher.search_path(path);
    }

    let fonts = searcher.into_fonts();

    // Collect font families
    let mut families: Vec<(String, Vec<FontVariant>)> = Vec::new();

    for font_slot in &fonts {
        if let Some(font) = font_slot.font() {
            let info = font.info();
            let family = info.family.clone();

            let variant = FontVariant {
                style: format!("{:?}", info.variant.style),
                weight: info.variant.weight.to_number(),
                stretch: format!("{:?}", info.variant.stretch),
                path: font_slot.path().map(|p| p.display().to_string())
                    .unwrap_or_else(|| "<embedded>".to_string()),
            };

            if let Some(pos) = families.iter().position(|(f, _)| f == &family) {
                families[pos].1.push(variant);
            } else {
                families.push((family, vec![variant]));
            }
        }
    }

    // Sort families alphabetically
    families.sort_by(|(a, _), (b, _)| a.cmp(b));

    for (family, variants) in &families {
        println!("{}", family);
        if args.variants {
            for variant in variants {
                println!("- Style: {}, Weight: {}, Stretch: {}, Path: {}",
                    variant.style,
                    variant.weight,
                    variant.stretch,
                    variant.path,
                );
            }
        }
    }
}

struct FontVariant {
    style: String,
    weight: u16,
    stretch: String,
    path: String,
}
