//! Info subcommand

use std::env;
use serde::{Deserialize, Serialize};

use crate::args::{InfoArgs, SerializeFormat};

const VERSION: &str = "0.14.2";
const FULL_HASH: &str = "ccc34be79ab2555cd26c519b1eab45a3e9ec757a";
const SHORT_HASH: &str = "ccc34be7";

#[derive(Serialize)]
struct InfoOutput {
    version: String,
    build: BuildInfo,
    features: FeatureInfo,
    fonts: FontInfo,
    packages: PackageInfo,
    env: EnvInfo,
}

#[derive(Serialize)]
struct BuildInfo {
    commit: String,
    platform: PlatformInfo,
    settings: SettingsInfo,
}

#[derive(Serialize)]
struct PlatformInfo {
    os: String,
    arch: String,
}

#[derive(Serialize)]
struct SettingsInfo {
    #[serde(rename = "self-update")]
    self_update: bool,
    #[serde(rename = "http-server")]
    http_server: bool,
}

#[derive(Serialize)]
struct FeatureInfo {
    html: bool,
    #[serde(rename = "a11y-extras")]
    a11y_extras: bool,
}

#[derive(Serialize)]
struct FontInfo {
    paths: Vec<String>,
    system: bool,
    embedded: bool,
}

#[derive(Serialize)]
struct PackageInfo {
    #[serde(rename = "package-path")]
    package_path: String,
    #[serde(rename = "package-cache-path")]
    package_cache_path: String,
}

#[derive(Serialize)]
struct EnvInfo {
    #[serde(rename = "TYPST_CERT")]
    typst_cert: Option<String>,
    #[serde(rename = "TYPST_FEATURES")]
    typst_features: Option<String>,
    #[serde(rename = "TYPST_FONT_PATHS")]
    typst_font_paths: Option<String>,
    #[serde(rename = "TYPST_IGNORE_SYSTEM_FONTS")]
    typst_ignore_system_fonts: Option<String>,
    #[serde(rename = "TYPST_IGNORE_EMBEDDED_FONTS")]
    typst_ignore_embedded_fonts: Option<String>,
    #[serde(rename = "TYPST_PACKAGE_CACHE_PATH")]
    typst_package_cache_path: Option<String>,
    #[serde(rename = "TYPST_PACKAGE_PATH")]
    typst_package_path: Option<String>,
    #[serde(rename = "TYPST_ROOT")]
    typst_root: Option<String>,
    #[serde(rename = "TYPST_UPDATE_BACKUP_PATH")]
    typst_update_backup_path: Option<String>,
    #[serde(rename = "SOURCE_DATE_EPOCH")]
    source_date_epoch: Option<String>,
    #[serde(rename = "XDG_CACHE_HOME")]
    xdg_cache_home: Option<String>,
    #[serde(rename = "XDG_DATA_HOME")]
    xdg_data_home: Option<String>,
    #[serde(rename = "FONTCONFIG_FILE")]
    fontconfig_file: Option<String>,
    #[serde(rename = "OPENSSL_CONF")]
    openssl_conf: Option<String>,
    #[serde(rename = "NO_COLOR")]
    no_color: Option<String>,
    #[serde(rename = "NO_PROXY")]
    no_proxy: Option<String>,
    #[serde(rename = "HTTP_PROXY")]
    http_proxy: Option<String>,
    #[serde(rename = "HTTPS_PROXY")]
    https_proxy: Option<String>,
    #[serde(rename = "ALL_PROXY")]
    all_proxy: Option<String>,
}

fn get_data_dir() -> String {
    if let Ok(xdg) = env::var("XDG_DATA_HOME") {
        format!("{}/typst/packages", xdg)
    } else if let Ok(home) = env::var("HOME") {
        format!("{}/.local/share/typst/packages", home)
    } else {
        "/typst/packages".to_string()
    }
}

fn get_cache_dir() -> String {
    if let Ok(xdg) = env::var("XDG_CACHE_HOME") {
        format!("{}/typst/packages", xdg)
    } else if let Ok(home) = env::var("HOME") {
        format!("{}/.cache/typst/packages", home)
    } else {
        "/tmp/typst/packages".to_string()
    }
}

fn get_env(name: &str) -> Option<String> {
    env::var(name).ok()
}

fn get_os() -> String {
    if cfg!(target_os = "linux") {
        "linux".to_string()
    } else if cfg!(target_os = "macos") {
        "macos".to_string()
    } else if cfg!(target_os = "windows") {
        "windows".to_string()
    } else {
        "unknown".to_string()
    }
}

fn get_arch() -> String {
    if cfg!(target_arch = "x86_64") {
        "x86_64".to_string()
    } else if cfg!(target_arch = "aarch64") {
        "aarch64".to_string()
    } else {
        "unknown".to_string()
    }
}

pub fn run(args: InfoArgs) {
    let font_paths: Vec<String> = env::var("TYPST_FONT_PATHS")
        .unwrap_or_default()
        .split(':')
        .filter(|s| !s.is_empty())
        .map(|s| s.to_string())
        .collect();

    let system_fonts = env::var("TYPST_IGNORE_SYSTEM_FONTS").is_err();
    let embedded_fonts = env::var("TYPST_IGNORE_EMBEDDED_FONTS").is_err();

    let info = InfoOutput {
        version: VERSION.to_string(),
        build: BuildInfo {
            commit: FULL_HASH.to_string(),
            platform: PlatformInfo {
                os: get_os(),
                arch: get_arch(),
            },
            settings: SettingsInfo {
                self_update: false,
                http_server: true,
            },
        },
        features: FeatureInfo {
            html: false,
            a11y_extras: false,
        },
        fonts: FontInfo {
            paths: font_paths,
            system: system_fonts,
            embedded: embedded_fonts,
        },
        packages: PackageInfo {
            package_path: env::var("TYPST_PACKAGE_PATH").unwrap_or_else(|_| get_data_dir()),
            package_cache_path: env::var("TYPST_PACKAGE_CACHE_PATH").unwrap_or_else(|_| get_cache_dir()),
        },
        env: EnvInfo {
            typst_cert: get_env("TYPST_CERT"),
            typst_features: get_env("TYPST_FEATURES"),
            typst_font_paths: get_env("TYPST_FONT_PATHS"),
            typst_ignore_system_fonts: get_env("TYPST_IGNORE_SYSTEM_FONTS"),
            typst_ignore_embedded_fonts: get_env("TYPST_IGNORE_EMBEDDED_FONTS"),
            typst_package_cache_path: get_env("TYPST_PACKAGE_CACHE_PATH"),
            typst_package_path: get_env("TYPST_PACKAGE_PATH"),
            typst_root: get_env("TYPST_ROOT"),
            typst_update_backup_path: get_env("TYPST_UPDATE_BACKUP_PATH"),
            source_date_epoch: get_env("SOURCE_DATE_EPOCH"),
            xdg_cache_home: get_env("XDG_CACHE_HOME"),
            xdg_data_home: get_env("XDG_DATA_HOME"),
            fontconfig_file: get_env("FONTCONFIG_FILE"),
            openssl_conf: get_env("OPENSSL_CONF"),
            no_color: get_env("NO_COLOR"),
            no_proxy: get_env("NO_PROXY"),
            http_proxy: get_env("HTTP_PROXY"),
            https_proxy: get_env("HTTPS_PROXY"),
            all_proxy: get_env("ALL_PROXY"),
        },
    };

    if let Some(format) = &args.format {
        match format {
            SerializeFormat::Json => {
                let output = if args.pretty {
                    serde_json::to_string_pretty(&info).unwrap()
                } else {
                    serde_json::to_string(&info).unwrap()
                };
                println!("{}", output);
            }
            SerializeFormat::Yaml => {
                let output = serde_yaml::to_string(&info).unwrap();
                print!("{}", output);
            }
        }
    } else {
        // Human-readable output
        println!("Version {} ({}, {} on {})", VERSION, SHORT_HASH, get_os(), get_arch());
        println!();
        println!("Build settings");
        println!("  self-update off (Update Typst via `typst update`)");
        println!("  http-server on  (Serve HTML via `typst watch`)");
        println!();
        println!("Features");
        println!("  html        off (Experimental HTML support)");
        println!("  a11y-extras off (Experimental accessibility additions)");
        println!();
        println!("Fonts");
        let custom_paths = info.fonts.paths.join(", ");
        if custom_paths.is_empty() {
            println!("  Custom font paths <none>");
        } else {
            println!("  Custom font paths {}", custom_paths);
        }
        println!("  System fonts   {}", if info.fonts.system { "on" } else { "off" });
        println!("  Embedded fonts {}", if info.fonts.embedded { "on" } else { "off" });
        println!();
        println!("Packages");
        println!("  Package path       {}", info.packages.package_path);
        println!("  Package cache path {}", info.packages.package_cache_path);
        println!();
        println!("Environment variables");
        print_env_var("TYPST_CERT", &info.env.typst_cert);
        print_env_var("TYPST_FEATURES", &info.env.typst_features);
        print_env_var("TYPST_FONT_PATHS", &info.env.typst_font_paths);
        print_env_var("TYPST_IGNORE_SYSTEM_FONTS", &info.env.typst_ignore_system_fonts);
        print_env_var("TYPST_IGNORE_EMBEDDED_FONTS", &info.env.typst_ignore_embedded_fonts);
        print_env_var("TYPST_PACKAGE_CACHE_PATH", &info.env.typst_package_cache_path);
        print_env_var("TYPST_PACKAGE_PATH", &info.env.typst_package_path);
        print_env_var("TYPST_ROOT", &info.env.typst_root);
        print_env_var("TYPST_UPDATE_BACKUP_PATH", &info.env.typst_update_backup_path);
        print_env_var("SOURCE_DATE_EPOCH", &info.env.source_date_epoch);
        print_env_var("XDG_CACHE_HOME", &info.env.xdg_cache_home);
        print_env_var("XDG_DATA_HOME", &info.env.xdg_data_home);
        print_env_var("FONTCONFIG_FILE", &info.env.fontconfig_file);
        print_env_var("OPENSSL_CONF", &info.env.openssl_conf);
        print_env_var("NO_COLOR", &info.env.no_color);
        print_env_var("NO_PROXY", &info.env.no_proxy);
        print_env_var("HTTP_PROXY", &info.env.http_proxy);
        print_env_var("HTTPS_PROXY", &info.env.https_proxy);
        print_env_var("ALL_PROXY", &info.env.all_proxy);
    }
}

fn print_env_var(name: &str, value: &Option<String>) {
    let max_len = 28;
    let padding = " ".repeat(max_len.saturating_sub(name.len()));
    match value {
        Some(v) => println!("  {}{}{}", name, padding, v),
        None => println!("  {}{}<unset>", name, padding),
    }
}
