fn print_env_var(name: &str, value: &Option<String>) {
    let max_len = 28;
    let padding = " ".repeat(max_len.saturating_sub(name.len()));
    match value {
        Some(v) => println!("  {}{}{}", name, padding, v),
        None => println!("  {}{}<unset>", name, padding),
    }
}
