fn create_world(input: &str, args: &WorldArgs) -> Result<SystemWorld, String> {
    SystemWorld::new(input, args, args.creation_timestamp)
}

fn determine_format(format: &Option<OutputFormat>, output: &str) -> OutputFormat {
    if let Some(f) = format {
        return f.clone();
    }

    if output == "-" {
        return OutputFormat::Pdf;
    }

    // Infer from extension
    let lower = output.to_lowercase();
    if lower.ends_with(".pdf") {
        OutputFormat::Pdf
    } else if lower.ends_with(".png") {
        OutputFormat::Png
    } else if lower.ends_with(".svg") {
        OutputFormat::Svg
    } else if lower.ends_with(".html") {
        OutputFormat::Html
    } else {
        OutputFormat::Pdf
    }
}

fn export_document(
    document: &typst::doc::Document,
    output: &str,
    format: &OutputFormat,
    args: &CompileArgs,
) -> Result<(), String> {
    let pages: Vec<usize> = if let Some(pages_str) = &args.pages {
        parse_page_ranges(pages_str, document.pages.len())
            .map_err(|e| format!("invalid page range: {}", e))?
    } else {
        (0..document.pages.len()).collect()
    };

    match format {
        OutputFormat::Pdf => {
            export_pdf(document, output, args, &pages)
        }
        OutputFormat::Png => {
            export_png(document, output, args, &pages)
        }
        OutputFormat::Svg => {
            export_svg(document, output, &pages)
        }
        OutputFormat::Html => {
            export_html(document, output)
        }
    }
}

fn export_pdf(
    document: &typst::doc::Document,
    output: &str,
    args: &CompileArgs,
    pages: &[usize],
) -> Result<(), String> {
    let options = typst_pdf::PdfOptions {
        ident: typst::foundations::Smart::Auto,
        timestamp: None, // TODO: handle creation timestamp
        page_ranges: None,
        standards: typst_pdf::PdfStandards::default(),
    };

    let pdf = typst_pdf::pdf(document, &options)
        .map_err(|e| format!("PDF export failed: {:?}", e))?;

    if output == "-" {
        io::stdout().write_all(&pdf).map_err(|e| e.to_string())?;
    } else {
        std::fs::write(output, &pdf).map_err(|e| e.to_string())?;
    }

    Ok(())
}

fn export_png(
    document: &typst::doc::Document,
    output: &str,
    args: &CompileArgs,
    pages: &[usize],
) -> Result<(), String> {
    let num_pages = document.pages.len();

    for &page_idx in pages {
        let page = document.pages.get(page_idx)
            .ok_or_else(|| format!("page {} not found", page_idx + 1))?;

        let pixmap = typst_render::render(page, args.ppi as f32 / 72.0, typst::visualize::Color::WHITE);
        let png_data = pixmap.encode_png()
            .map_err(|e| format!("PNG encoding failed: {}", e))?;

        let actual_output = if num_pages > 1 || output.contains('{') {
            apply_page_template(output, page_idx + 1, num_pages)
        } else {
            output.to_string()
        };

        if actual_output == "-" {
            io::stdout().write_all(&png_data).map_err(|e| e.to_string())?;
        } else {
            std::fs::write(&actual_output, &png_data).map_err(|e| e.to_string())?;
        }
    }

    Ok(())
}

fn export_svg(
    document: &typst::doc::Document,
    output: &str,
    pages: &[usize],
) -> Result<(), String> {
    let num_pages = document.pages.len();

    for &page_idx in pages {
        let page = document.pages.get(page_idx)
            .ok_or_else(|| format!("page {} not found", page_idx + 1))?;

        let svg = typst_svg::svg(page);

        let actual_output = if num_pages > 1 || output.contains('{') {
            apply_page_template(output, page_idx + 1, num_pages)
        } else {
            output.to_string()
        };

        if actual_output == "-" {
            io::stdout().write_all(svg.as_bytes()).map_err(|e| e.to_string())?;
        } else {
            std::fs::write(&actual_output, svg.as_bytes()).map_err(|e| e.to_string())?;
        }
    }

    Ok(())
}

fn export_html(
    document: &typst::doc::Document,
    output: &str,
) -> Result<(), String> {
    Err("HTML export requires the 'html' experimental feature".to_string())
}

fn apply_page_template(template: &str, page: usize, total: usize) -> String {
    let total_digits = total.to_string().len();
    let page_str = format!("{:0>width$}", page, width = total_digits);

    template
        .replace("{p}", &page.to_string())
        .replace("{0p}", &page_str)
        .replace("{t}", &total.to_string())
}

fn parse_page_ranges(pages_str: &str, total: usize) -> Result<Vec<usize>, String> {
    let mut result = Vec::new();

    for part in pages_str.split(',') {
        let part = part.trim();
        if let Some((start_str, end_str)) = part.split_once('-') {
            let start: usize = start_str.trim().parse()
                .map_err(|_| format!("invalid page number: {}", start_str))?;
            if end_str.trim().is_empty() {
                // Open range: "8-"
                for i in start..=total {
                    if i >= 1 {
                        result.push(i - 1);
                    }
                }
            } else {
                let end: usize = end_str.trim().parse()
                    .map_err(|_| format!("invalid page number: {}", end_str))?;
                for i in start..=end {
                    if i >= 1 && i <= total {
                        result.push(i - 1);
                    }
                }
            }
        } else {
            let page: usize = part.parse()
                .map_err(|_| format!("invalid page number: {}", part))?;
            if page >= 1 && page <= total {
                result.push(page - 1);
            }
        }
    }

    result.sort();
    result.dedup();
    Ok(result)
}

fn print_diagnostics(
    diagnostics: &[SourceDiagnostic],
    format: &DiagnosticFormat,
    color: &ColorChoice,
    world: &SystemWorld,
) {
    let use_color = match color {
        ColorChoice::Always => true,
        ColorChoice::Never => false,
        ColorChoice::Auto => {
            // Check if stderr is a terminal
            std::io::IsTerminal::is_terminal(&std::io::stderr())
        }
    };

    crate::diagnostics::print_diagnostics(diagnostics, format, use_color, world);
}

fn write_deps(
    deps_path: &str,
    input_path: &str,
    output_path: &str,
    format: &DepsFormat,
    world: &SystemWorld,
) {
    // Collect all source files
    let mut input_paths = vec![input_path.to_string()];

    // TODO: collect actual dependencies

    if let Err(e) = crate::deps::write_deps(deps_path, &input_paths, output_path, format) {
        eprintln!("warning: failed to write deps: {}", e);
    }
}

fn eval_expression(
    world: &SystemWorld,
    expression: &str,
    _args: &WorldArgs,
) -> Result<Value, Vec<SourceDiagnostic>> {
    use typst::foundations::{Scope, Value};
    use typst::eval::Tracer;

    // We need to evaluate the expression in the context of the world
    // Create a synthetic source that evaluates the expression
    let code = format!("{}", expression);

    // Use typst's eval function
    // This evaluates a Typst code expression
    typst::eval::eval_string(world, &code, typst::eval::EvalMode::Code)
}

fn run_query_on_document(
    document: &typst::doc::Document,
    selector_str: &str,
    field: &Option<String>,
    one: bool,
    world: &SystemWorld,
) -> Result<Value, String> {
    // Parse selector and run query
    use typst::foundations::{Array, Value};

    // We need to evaluate the selector expression
    let query_code = format!("query({})", selector_str);

    let result = typst::eval::eval_string(world, &query_code, typst::eval::EvalMode::Code)
        .map_err(|e| format!("query failed: {:?}", e))?;

    let arr = match result {
        Value::Array(a) => a,
        _ => return Err("query did not return an array".to_string()),
    };

    // Apply field filter
    let filtered: Vec<Value> = if let Some(field_name) = field {
        arr.iter().filter_map(|v| {
            match v {
                Value::Content(c) => c.fields().into_iter()
                    .find(|(f, _)| f.as_str() == field_name.as_str())
                    .map(|(_, v)| v),
                Value::Dict(d) => d.get(field_name.as_str()).cloned(),
                _ => None,
            }
        }).collect()
    } else {
        arr.iter().cloned().collect()
    };

    if one {
        match filtered.len() {
            0 => Err("query returned no results, expected exactly one".to_string()),
            1 => Ok(filtered.into_iter().next().unwrap()),
            n => Err(format!("query returned {} results, expected exactly one", n)),
        }
    } else {
        Ok(Value::Array(Array::from(filtered)))
    }
}
