use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};

use typst::diag::{EcoString, SourceDiagnostic, Severity};
use typst::foundations::Value;

use crate::args::*;
use crate::world::SystemWorld;

pub fn run(args: CompileArgs, color: &ColorChoice) -> i32 {
    let input_path = args.input.clone();

    // Determine output path/format
    let output = match &args.output {
        Some(o) => o.clone(),
        None => {
            // Default to input with .pdf extension
            if input_path == "-" {
                eprintln!("error: please specify an output path when reading from stdin");
                return 1;
            }
            let p = Path::new(&input_path);
            let stem = p.file_stem().unwrap_or_default();
            format!("{}.pdf", stem.to_string_lossy())
        }
    };

    let format = determine_format(&args.format, &output);

    // Create the world
    let world = match create_world(&input_path, &args.world) {
        Ok(w) => w,
        Err(e) => {
            eprintln!("error: {}", e);
            return 1;
        }
    };

    // Load stdin if needed
    if input_path == "-" {
        let mut stdin_content = String::new();
        io::stdin().read_to_string(&mut stdin_content).unwrap_or(0);
        let source = typst::syntax::Source::new(
            world.main_id(),
            stdin_content,
        );
        world.set_main_source(source);
    } else if !Path::new(&input_path).exists() {
        eprintln!("error: input file not found (searched at {})", input_path);
        return 1;
    }

    // Compile
    let mut tracer = typst::diag::Tracer::new();
    let result = typst::compile(&world, &mut tracer);
    let warnings = tracer.warnings();

    match result {
        Ok(document) => {
            // Print warnings
            print_diagnostics(&warnings, &args.world.diagnostic_format, color, &world);

            // Export
            match export_document(&document, &output, &format, &args) {
                Ok(()) => {
                    // Write deps if requested
                    if let Some(deps_path) = &args.deps {
                        write_deps(deps_path, &input_path, &output, &args.deps_format, &world);
                    }
                    0
                }
                Err(e) => {
                    eprintln!("error: {}", e);
                    1
                }
            }
        }
        Err(errors) => {
            print_diagnostics(&errors, &args.world.diagnostic_format, color, &world);
            1
        }
    }
}

pub fn watch(args: WatchArgs, color: &ColorChoice) -> i32 {
    eprintln!("error: watch mode requires file system notifications");
    1
}

pub fn eval(args: EvalArgs, color: &ColorChoice) -> i32 {
    let input_file = args.input_file.as_deref();

    // Build a minimal world
    let input_path = input_file.unwrap_or("-");

    let world = match create_world(input_path, &args.world) {
        Ok(w) => w,
        Err(e) => {
            eprintln!("error: {}", e);
            return 1;
        }
    };

    // Load file if specified
    if let Some(file) = input_file {
        if file == "-" {
            let mut stdin_content = String::new();
            io::stdin().read_to_string(&mut stdin_content).unwrap_or(0);
            let source = typst::syntax::Source::new(world.main_id(), stdin_content);
            world.set_main_source(source);
        } else if !Path::new(file).exists() {
            eprintln!("error: input file not found (searched at {})", file);
            return 1;
        }
    } else {
        // Create a synthetic empty file as context
        let source = typst::syntax::Source::new(world.main_id(), String::new());
        world.set_main_source(source);
    }

    // Evaluate the expression
    let expression = format!("#let __result__ = ({})\n__result__", args.expression);
    let eval_result = eval_expression(&world, &args.expression, &args.world);

    match eval_result {
        Ok(value) => {
            let output = crate::serialize::serialize_value(&value, &args.format, args.pretty);
            println!("{}", output);
            0
        }
        Err(errors) => {
            print_diagnostics(&errors, &args.world.diagnostic_format, color, &world);
            1
        }
    }
}

pub fn query(args: QueryArgs, color: &ColorChoice) -> i32 {
    // Issue deprecation warning
    eprintln!("warning: the `typst query` subcommand is deprecated");
    eprintln!(" = hint: use `typst eval 'query({})' --in {}` instead", 
        args.selector, args.input);

    let world = match create_world(&args.input, &args.world) {
        Ok(w) => w,
        Err(e) => {
            eprintln!("error: {}", e);
            return 1;
        }
    };

    if args.input == "-" {
        let mut stdin_content = String::new();
        io::stdin().read_to_string(&mut stdin_content).unwrap_or(0);
        let source = typst::syntax::Source::new(world.main_id(), stdin_content);
        world.set_main_source(source);
    } else if !Path::new(&args.input).exists() {
        eprintln!("error: input file not found (searched at {})", args.input);
        return 1;
    }

    // Compile the document first
    let mut tracer = typst::diag::Tracer::new();
    let result = typst::compile(&world, &mut tracer);

    match result {
