/// The system world provides access to files and fonts for compilation
pub struct SystemWorld {
    root: PathBuf,
    library: OnceLock<Library>,
    book: FontBook,
    fonts: Vec<FontSlot>,
    main: FileId,
    inputs: Dict,
    package_storage: PackageStorage,
    sources: Mutex<HashMap<FileId, FileResult<Source>>>,
    files: Mutex<HashMap<FileId, FileResult<Bytes>>>,
    stdin_source: OnceLock<Source>,
    creation_timestamp: Option<i64>,
}

