        input: &str,
        args: &WorldArgs,
        creation_timestamp: Option<i64>,
    ) -> Result<Self, String> {
        // Determine the root directory and main file ID
        let (root, main) = if input == "-" {
            let root = args.root.clone()
                .unwrap_or_else(|| std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
