            let canon = input_path.canonicalize()
                .unwrap_or_else(|_| input_path.clone());

            let root = if let Some(root) = &args.root {
                if root.is_absolute() {
                    root.clone()
                } else {
                    std::env::current_dir()
                        .unwrap_or_else(|_| PathBuf::from("."))
                        .join(root)
                        .canonicalize()
                        .unwrap_or_else(|_| root.clone())
                }
            } else {
                canon.parent()
                    .unwrap_or(Path::new("."))
                    .to_path_buf()
            };

            // Create VirtualPath relative to root
            let rel = canon.strip_prefix(&root)
                .unwrap_or_else(|_| &canon);
            let vpath = VirtualPath::new(rel);
            let main = FileId::new(None, vpath);

            (root, main)
        };

