fn create_world(input: &str, args: &WorldArgs) -> Result<SystemWorld, String> {
    if input != "-" && !Path::new(input).exists() {
        return Err(format!("input file not found (searched at {})", input));
    }
    SystemWorld::new(input, args, args.creation_timestamp)
}

fn build_eval_world(input_file: Option<&str>, args: &WorldArgs) -> Result<SystemWorld, String> {
    let input = input_file.unwrap_or("-");
    if input != "-" && !Path::new(input).exists() {
        return Err(format!("input file not found (searched at {})", input));
    }
    SystemWorld::new(input, args, args.creation_timestamp)
}

fn compile_document(world: &SystemWorld) -> Result<(typst::model::Document, Vec<SourceDiagnostic>), Vec<SourceDiagnostic>> {
    let mut tracer = typst::diag::Tracer::new();
    let result = typst::compile(world, &mut tracer);
    let warnings = tracer.warnings();

    match result {
        Ok(doc) => Ok((doc, warnings)),
        Err(errors) => Err(errors),
    }
}

fn eval_code(world: &SystemWorld, code: &str) -> Result<Value, Vec<SourceDiagnostic>> {
    typst::eval::eval_string(
        world,
        code,
        typst::eval::EvalMode::Code,
    )
}

fn determine_format(format: &Option<OutputFormat>, output: &str) -> OutputFormat {
    if let Some(f) = format {
        return f.clone();
    }

    if output == "-" {
        return OutputFormat::Pdf;
    }

    // Strip page template first
    let base = output
        .replace("{p}", "X")
        .replace("{0p}", "X")
        .replace("{t}", "X");

    let lower = base.to_lowercase();
    if lower.ends_with(".pdf") {
        OutputFormat::Pdf
    } else if lower.ends_with(".png") {
        OutputFormat::Png
    } else if lower.ends_with(".svg") {
        OutputFormat::Svg
    } else if lower.ends_with(".html") || lower.ends_with(".htm") {
        OutputFormat::Html
    } else {
        OutputFormat::Pdf
    }
}

fn export_document(
    document: &typst::model::Document,
    output: &str,
    format: &OutputFormat,
    args: &CompileArgs,
) -> Result<(), String> {
    // Parse page ranges
    let num_pages = document.pages.len();
    let pages: Vec<usize> = if let Some(pages_str) = &args.pages {
        parse_page_ranges(pages_str, num_pages)
            .map_err(|e| format!("invalid page range: {}", e))?
    } else {
        (0..num_pages).collect()
    };

    match format {
        OutputFormat::Pdf => export_pdf(document, output, args),
        OutputFormat::Png => export_png(document, output, args, &pages),
        OutputFormat::Svg => export_svg(document, output, &pages),
        OutputFormat::Html => export_html(document, output),
    }
}

fn export_pdf(
    document: &typst::model::Document,
    output: &str,
    args: &CompileArgs,
) -> Result<(), String> {
    use typst_pdf::{PdfOptions, PdfStandards};

    let mut standards = PdfStandards::default();
    // TODO: handle args.pdf_standard

    let options = PdfOptions {
        ident: typst::foundations::Smart::Auto,
        timestamp: None,
        page_ranges: None,
        standards,
    };

    let pdf_data = typst_pdf::pdf(document, &options)
        .map_err(|e| format!("PDF export failed: {:?}", e))?;

    write_output(output, &pdf_data)
}

fn export_png(
    document: &typst::model::Document,
    output: &str,
    args: &CompileArgs,
    pages: &[usize],
) -> Result<(), String> {
    let num_pages = document.pages.len();

    if num_pages > 1 && !output.contains('{') && output != "-" {
        return Err(format!(
            "cannot export multiple pages to a single file without a page template in the output path;\n\
             use `{{p}}` for page numbers, `{{0p}}` for zero padded page numbers, `{{t}}` for page count;\n\
             for example, `{}`",
            output.replace(".png", "-{p}.png")
        ));
    }

    for &page_idx in pages {
        let page = document.pages.get(page_idx)
            .ok_or_else(|| format!("page {} not found", page_idx + 1))?;

        let pixmap = typst_render::render(
            page,
            args.ppi as f32 / 72.0,
            typst::visualize::Color::WHITE,
        );

        let png_data = pixmap.encode_png()
            .map_err(|e| format!("PNG encoding failed: {}", e))?;

        let actual_output = apply_page_template(output, page_idx + 1, num_pages);
        write_output(&actual_output, &png_data)?;
    }

    Ok(())
}

fn export_svg(
    document: &typst::model::Document,
    output: &str,
    pages: &[usize],
) -> Result<(), String> {
    let num_pages = document.pages.len();

    if num_pages > 1 && !output.contains('{') && output != "-" {
        return Err(format!(
            "cannot export multiple pages to a single file without a page template in the output path"
        ));
    }

    for &page_idx in pages {
        let page = document.pages.get(page_idx)
            .ok_or_else(|| format!("page {} not found", page_idx + 1))?;

        let svg = typst_svg::svg(page);

        let actual_output = apply_page_template(output, page_idx + 1, num_pages);
        write_output(&actual_output, svg.as_bytes())?;
    }

    Ok(())
}

fn export_html(
    _document: &typst::model::Document,
    _output: &str,
) -> Result<(), String> {
    Err("HTML export requires enabling the `html` experimental feature with `--features html`".to_string())
}

fn write_output(output: &str, data: &[u8]) -> Result<(), String> {
    if output == "-" {
        io::stdout().write_all(data).map_err(|e| e.to_string())
    } else {
        std::fs::write(output, data).map_err(|e| e.to_string())
    }
}

fn apply_page_template(template: &str, page: usize, total: usize) -> String {
    if !template.contains('{') {
        return template.to_string();
    }

    let total_digits = total.to_string().len();
    let page_padded = format!("{:0>width$}", page, width = total_digits);

    template
        .replace("{p}", &page.to_string())
        .replace("{0p}", &page_padded)
        .replace("{t}", &total.to_string())
}

fn parse_page_ranges(pages_str: &str, total: usize) -> Result<Vec<usize>, String> {
    let mut result = Vec::new();

    for part in pages_str.split(',') {
        let part = part.trim();
        if part.is_empty() {
            continue;
        }

        if let Some((start_str, end_str)) = part.split_once('-') {
            let start: usize = start_str.trim().parse()
                .map_err(|_| format!("invalid page number: '{}'", start_str.trim()))?;

            if end_str.trim().is_empty() {
                // Open range: "8-" means page 8 to end
                for i in start..=total {
                    if i >= 1 {
                        result.push(i - 1);
                    }
                }
            } else {
                let end: usize = end_str.trim().parse()
                    .map_err(|_| format!("invalid page number: '{}'", end_str.trim()))?;
                for i in start..=end {
                    if i >= 1 && i <= total {
                        result.push(i - 1);
                    }
                }
            }
        } else {
            let page: usize = part.parse()
                .map_err(|_| format!("invalid page number: '{}'", part))?;
            if page >= 1 && page <= total {
                result.push(page - 1);
            }
        }
    }

    result.sort();
    result.dedup();
    Ok(result)
}

fn print_diagnostics(
    diagnostics: &[SourceDiagnostic],
    format: &DiagnosticFormat,
    color: &ColorChoice,
    world: &SystemWorld,
) {
    let use_color = match color {
        ColorChoice::Always => true,
        ColorChoice::Never => false,
        ColorChoice::Auto => {
            use std::io::IsTerminal;
            std::io::stderr().is_terminal()
        }
    };

    crate::diagnostics::print_diagnostics(diagnostics, format, use_color, world);
}

fn write_deps(
    deps_path: &str,
    input_paths: &[String],
    output_path: &str,
    format: &DepsFormat,
) {
    if let Err(e) = crate::deps::write_deps(deps_path, input_paths, output_path, format) {
        eprintln!("warning: failed to write deps: {}", e);
    }
}

fn serialize_value(value: &Value, format: &SerializeFormat, pretty: bool) -> String {
    crate::serialize::serialize_value(value, format, pretty)
}

fn apply_query_filter(
    value: Value,
    field: &Option<String>,
    one: bool,
) -> Result<Value, String> {
    use typst::foundations::Array;

    let arr = match value {
        Value::Array(a) => a,
        other => {
            if one {
                return Ok(other);
            }
            return Ok(Value::Array(Array::new()));
        }
    };

    let filtered: Vec<Value> = if let Some(field_name) = field {
        arr.iter().filter_map(|v| {
            match v {
                Value::Dict(d) => d.get(field_name.as_str()).cloned(),
                Value::Content(c) => {
                    // Try to get field from content
                    c.get(field_name.as_str().into(), typst::foundations::StyleChain::default()).ok()
                },
                _ => None,
            }
        }).collect()
    } else {
        arr.iter().cloned().collect()
    };

    if one {
        match filtered.len() {
            0 => Err("query returned no results, expected exactly one".to_string()),
            1 => Ok(filtered.into_iter().next().unwrap()),
            n => Err(format!("query returned {} results, expected exactly one", n)),
        }
    } else {
        Ok(Value::Array(Array::from_iter(filtered)))
    }
}

fn make_relative_path_display(path: &Path) -> String {
    // Make path look like "../tmp/file.typ" relative to parent
    if let Ok(cwd) = std::env::current_dir() {
        if let Some(parent) = cwd.parent() {
            if let Ok(rel) = path.strip_prefix(parent) {
                return format!("../{}", rel.display());
            }
        }
    }
    path.display().to_string()
}
