    // Strip page template first
    let base = output
        .replace("{p}", "X")
        .replace("{0p}", "X")
        .replace("{t}", "X");

    let lower = base.to_lowercase();
    if lower.ends_with(".pdf") {
        OutputFormat::Pdf
    } else if lower.ends_with(".png") {
        OutputFormat::Png
    } else if lower.ends_with(".svg") {
        OutputFormat::Svg
    } else if lower.ends_with(".html") || lower.ends_with(".htm") {
