        let pixmap = typst_render::render(
            page,
            args.ppi as f32 / 72.0,
            typst::visualize::Color::WHITE,
        );

        let png_data = pixmap.encode_png()
            .map_err(|e| format!("PNG encoding failed: {}", e))?;

        let actual_output = apply_page_template(output, page_idx + 1, num_pages);
        write_output(&actual_output, &png_data)?;
    }

    Ok(())
}

fn export_svg(
    document: &typst::model::Document,
    output: &str,
    pages: &[usize],
) -> Result<(), String> {
    let num_pages = document.pages.len();

    if num_pages > 1 && !output.contains('{') && output != "-" {
        return Err(format!(
            "cannot export multiple pages to a single file without a page template in the output path"
        ));
    }

    for &page_idx in pages {
        let page = document.pages.get(page_idx)
            .ok_or_else(|| format!("page {} not found", page_idx + 1))?;

        let svg = typst_svg::svg(page);

        let actual_output = apply_page_template(output, page_idx + 1, num_pages);
        write_output(&actual_output, svg.as_bytes())?;
    }

    Ok(())
}

fn export_html(
    _document: &typst::model::Document,
    _output: &str,
) -> Result<(), String> {
    Err("HTML export requires enabling the `html` experimental feature with `--features html`".to_string())
}

fn write_output(output: &str, data: &[u8]) -> Result<(), String> {
    if output == "-" {
        io::stdout().write_all(data).map_err(|e| e.to_string())
    } else {
        std::fs::write(output, data).map_err(|e| e.to_string())
    }
}

fn apply_page_template(template: &str, page: usize, total: usize) -> String {
    if !template.contains('{') {
        return template.to_string();
    }

    let total_digits = total.to_string().len();
    let page_padded = format!("{:0>width$}", page, width = total_digits);

    template
        .replace("{p}", &page.to_string())
        .replace("{0p}", &page_padded)
        .replace("{t}", &total.to_string())
}

fn parse_page_ranges(pages_str: &str, total: usize) -> Result<Vec<usize>, String> {
    let mut result = Vec::new();

    for part in pages_str.split(',') {
        let part = part.trim();
        if part.is_empty() {
            continue;
        }

        if let Some((start_str, end_str)) = part.split_once('-') {
            let start: usize = start_str.trim().parse()
                .map_err(|_| format!("invalid page number: '{}'", start_str.trim()))?;

            if end_str.trim().is_empty() {
                // Open range: "8-" means page 8 to end
                for i in start..=total {
                    if i >= 1 {
                        result.push(i - 1);
                    }
                }
            } else {
                let end: usize = end_str.trim().parse()
                    .map_err(|_| format!("invalid page number: '{}'", end_str.trim()))?;
                for i in start..=end {
                    if i >= 1 && i <= total {
                        result.push(i - 1);
                    }
                }
            }
        } else {
            let page: usize = part.parse()
                .map_err(|_| format!("invalid page number: '{}'", part))?;
            if page >= 1 && page <= total {
                result.push(page - 1);
            }
        }
    }

    result.sort();
    result.dedup();
    Ok(result)
}

fn print_diagnostics(
    diagnostics: &[SourceDiagnostic],
    format: &DiagnosticFormat,
    color: &ColorChoice,
    world: &SystemWorld,
) {
    let use_color = match color {
        ColorChoice::Always => true,
        ColorChoice::Never => false,
        ColorChoice::Auto => {
            use std::io::IsTerminal;
            std::io::stderr().is_terminal()
        }
    };

    crate::diagnostics::print_diagnostics(diagnostics, format, use_color, world);
}

fn write_deps(
    deps_path: &str,
    input_paths: &[String],
    output_path: &str,
    format: &DepsFormat,
) {
    if let Err(e) = crate::deps::write_deps(deps_path, input_paths, output_path, format) {
        eprintln!("warning: failed to write deps: {}", e);
    }
}

fn serialize_value(value: &Value, format: &SerializeFormat, pretty: bool) -> String {
    crate::serialize::serialize_value(value, format, pretty)
}

fn apply_query_filter(
    value: Value,
    field: &Option<String>,
    one: bool,
) -> Result<Value, String> {
    use typst::foundations::Array;

    let arr = match value {
        Value::Array(a) => a,
        other => {
            if one {
                return Ok(other);
            }
            return Ok(Value::Array(Array::new()));
        }
    };

    let filtered: Vec<Value> = if let Some(field_name) = field {
        arr.iter().filter_map(|v| {
            match v {
                Value::Dict(d) => d.get(field_name.as_str()).cloned(),
                Value::Content(c) => {
                    // Try to get field from content
                    c.get(field_name.as_str().into(), typst::foundations::StyleChain::default()).ok()
                },
                _ => None,
            }
        }).collect()
    } else {
        arr.iter().cloned().collect()
    };

    if one {
        match filtered.len() {
            0 => Err("query returned no results, expected exactly one".to_string()),
            1 => Ok(filtered.into_iter().next().unwrap()),
            n => Err(format!("query returned {} results, expected exactly one", n)),
        }
    } else {
        Ok(Value::Array(Array::from_iter(filtered)))
    }
}

fn make_relative_path_display(path: &Path) -> String {
    // Make path look like "../tmp/file.typ" relative to parent
    if let Ok(cwd) = std::env::current_dir() {
        if let Some(parent) = cwd.parent() {
            if let Ok(rel) = path.strip_prefix(parent) {
                return format!("../{}", rel.display());
            }
        }
    }
    path.display().to_string()
}
