    let span = diag.span;
    if let Some(id) = span.id() {
        if let Ok(src) = world.source(id) {
            if let Some(range) = src.range(span) {
                let line = src.byte_to_line(range.start).unwrap_or(0) + 1;
                let col = src.byte_to_column(range.start).unwrap_or(0) + 1;
                let path = format_path_for_id(id);
                let _ = writeln!(handle, "{}:{}:{}: {}: {}", path, line, col, severity_str(&diag.severity), msg);

                for hint in &diag.hints {
                    let _ = writeln!(handle, " = hint: {}", hint.as_str());
                }
                return;
            }
        }
    }

    let _ = writeln!(handle, "{}: {}", severity_str(&diag.severity), msg);
    for hint in &diag.hints {
        let _ = writeln!(handle, " = hint: {}", hint.as_str());
    }
}

fn print_human_diagnostic(
    diag: &SourceDiagnostic,
    world: &impl World,
    handle: &mut impl Write,
) {
    let msg = diag.message.as_str();
    let sev = severity_str(&diag.severity);

    let span = diag.span;
    if let Some(id) = span.id() {
        if let Ok(src) = world.source(id) {
            if let Some(range) = src.range(span) {
                let line_num = src.byte_to_line(range.start).unwrap_or(0);
                let col_num = src.byte_to_column(range.start).unwrap_or(0);
                let path = format_path_for_id(id);

                let _ = writeln!(handle, "{}: {}", sev, msg);
                let _ = writeln!(handle, "  ┌─ {}:{}:{}", path, line_num + 1, col_num + 1);
                let _ = writeln!(handle, "  │");

                // Show source lines
                let line_start = src.byte_to_line(range.start).unwrap_or(0);
                let line_end = src.byte_to_line(range.end.saturating_sub(1)).unwrap_or(line_start);

                for line_idx in line_start..=line_end {
                    let line_text = src.line(line_idx).unwrap_or("");
                    let line_no = line_idx + 1;
                    let line_no_str = line_no.to_string();
                    let _ = writeln!(handle, "{} │ {}", line_no_str, line_text);

                    // Calculate underline
                    let line_byte_start = src.line_to_byte(line_idx).unwrap_or(0);

                    let underline_start = if line_idx == line_start {
                        let char_offset = line_text[..range.start.saturating_sub(line_byte_start).min(line_text.len())].chars().count();
                        char_offset
                    } else {
                        0
                    };

                    let underline_end = if line_idx == line_end {
                        let end_byte = range.end.saturating_sub(line_byte_start).min(line_text.len());
                        line_text[..end_byte].chars().count()
                    } else {
                        line_text.chars().count()
                    };

                    let underline_len = underline_end.saturating_sub(underline_start).max(1);
                    let prefix_len = line_no_str.len() + 2; // " │ "
                    let spaces: String = " ".repeat(prefix_len + underline_start);
                    let underline: String = "^".repeat(underline_len);
                    let _ = writeln!(handle, "  │ {}{}", spaces, underline);
                }

                let _ = writeln!(handle, "");

                for hint in &diag.hints {
                    let _ = writeln!(handle, " = hint: {}", hint.as_str());
                }
                return;
            }
        }
    }

    // No span information
    let _ = writeln!(handle, "{}: {}", sev, msg);
    let _ = writeln!(handle, "");
    for hint in &diag.hints {
        let _ = writeln!(handle, " = hint: {}", hint.as_str());
    }
}

fn format_path_for_id(id: typst::syntax::FileId) -> String {
    let vpath = id.vpath();
    if let Some(pkg) = id.package() {
        format!("{}{}", pkg, vpath.as_rooted_path().display())
    } else {
        // Make it look relative - the original uses ".." prefix
        format!("..{}", vpath.as_rooted_path().display())
    }
}
