    } else {
        "unknown".to_string()
    }
}

fn get_arch() -> String {
    if cfg!(target_arch = "x86_64") {
        "x86_64".to_string()
    } else if cfg!(target_arch = "aarch64") {
        "aarch64".to_string()
    } else {
        "unknown".to_string()
    }
}

pub fn run(args: InfoArgs) {
    let font_paths: Vec<String> = match env::var("TYPST_FONT_PATHS") {
        Ok(s) if !s.is_empty() => {
            let sep = if cfg!(windows) { ';' } else { ':' };
            s.split(sep).filter(|s| !s.is_empty()).map(|s| s.to_string()).collect()
        }
        _ => Vec::new(),
    };

    let system_fonts = env::var("TYPST_IGNORE_SYSTEM_FONTS").is_err();
    let embedded_fonts = env::var("TYPST_IGNORE_EMBEDDED_FONTS").is_err();

    let info = InfoOutput {
        version: VERSION.to_string(),
        build: BuildInfo {
            commit: FULL_HASH.to_string(),
            platform: PlatformInfo {
                os: get_os(),
                arch: get_arch(),
            },
            settings: SettingsInfo {
                self_update: false,
                http_server: true,
            },
        },
        features: FeatureInfo {
            html: false,
            a11y_extras: false,
        },
        fonts: FontInfo {
            paths: font_paths,
            system: system_fonts,
            embedded: embedded_fonts,
        },
        packages: PackageInfo {
            package_path: env::var("TYPST_PACKAGE_PATH").unwrap_or_else(|_| get_data_dir()),
            package_cache_path: env::var("TYPST_PACKAGE_CACHE_PATH").unwrap_or_else(|_| get_cache_dir()),
        },
        env: EnvInfo {
            typst_cert: get_env("TYPST_CERT"),
            typst_features: get_env("TYPST_FEATURES"),
            typst_font_paths: get_env("TYPST_FONT_PATHS"),
            typst_ignore_system_fonts: get_env("TYPST_IGNORE_SYSTEM_FONTS"),
            typst_ignore_embedded_fonts: get_env("TYPST_IGNORE_EMBEDDED_FONTS"),
            typst_package_cache_path: get_env("TYPST_PACKAGE_CACHE_PATH"),
            typst_package_path: get_env("TYPST_PACKAGE_PATH"),
            typst_root: get_env("TYPST_ROOT"),
            typst_update_backup_path: get_env("TYPST_UPDATE_BACKUP_PATH"),
            source_date_epoch: get_env("SOURCE_DATE_EPOCH"),
            xdg_cache_home: get_env("XDG_CACHE_HOME"),
            xdg_data_home: get_env("XDG_DATA_HOME"),
            fontconfig_file: get_env("FONTCONFIG_FILE"),
            openssl_conf: get_env("OPENSSL_CONF"),
            no_color: get_env("NO_COLOR"),
            no_proxy: get_env("NO_PROXY"),
            http_proxy: get_env("HTTP_PROXY"),
            https_proxy: get_env("HTTPS_PROXY"),
            all_proxy: get_env("ALL_PROXY"),
        },
    };

    if let Some(format) = &args.format {
        match format {
            SerializeFormat::Json => {
                let output = if args.pretty {
                    serde_json::to_string_pretty(&info).unwrap()
                } else {
                    serde_json::to_string(&info).unwrap()
                };
                println!("{}", output);
            }
            SerializeFormat::Yaml => {
                let output = serde_yaml::to_string(&info).unwrap();
                print!("{}", output);
            }
        }
    } else {
        print_human_info(&info);
    }
}

fn print_human_info(info: &InfoOutput) {
    println!("Version {} ({}, {} on {})", 
        info.version, SHORT_HASH, info.build.platform.os, info.build.platform.arch);
    println!();
    println!("Build settings");
    println!("  {:<11} {} ({})", 
        "self-update", 
        if info.build.settings.self_update { "on " } else { "off" },
        "Update Typst via `typst update`");
    println!("  {:<11} {} ({})", 
        "http-server",
        if info.build.settings.http_server { "on " } else { "off" },
        "Serve HTML via `typst watch`");
    println!();
    println!("Features");
    println!("  {:<11} {} ({})",
        "html",
        if info.features.html { "on " } else { "off" },
        "Experimental HTML support");
    println!("  {:<11} {} ({})",
        "a11y-extras",
        if info.features.a11y_extras { "on " } else { "off" },
        "Experimental accessibility additions");
    println!();
    println!("Fonts");
    if info.fonts.paths.is_empty() {
        println!("  Custom font paths <none>");
    } else {
        println!("  Custom font paths {}", info.fonts.paths.join(":"));
    }
    println!("  System fonts   {}", if info.fonts.system { "on" } else { "off" });
    println!("  Embedded fonts {}", if info.fonts.embedded { "on" } else { "off" });
    println!();
    println!("Packages");
    println!("  {:<19}{}", "Package path", info.packages.package_path);
    println!("  {:<19}{}", "Package cache path", info.packages.package_cache_path);
    println!();
    println!("Environment variables");

    let env_vars = [
        ("TYPST_CERT", &info.env.typst_cert),
        ("TYPST_FEATURES", &info.env.typst_features),
        ("TYPST_FONT_PATHS", &info.env.typst_font_paths),
        ("TYPST_IGNORE_SYSTEM_FONTS", &info.env.typst_ignore_system_fonts),
        ("TYPST_IGNORE_EMBEDDED_FONTS", &info.env.typst_ignore_embedded_fonts),
        ("TYPST_PACKAGE_CACHE_PATH", &info.env.typst_package_cache_path),
        ("TYPST_PACKAGE_PATH", &info.env.typst_package_path),
        ("TYPST_ROOT", &info.env.typst_root),
        ("TYPST_UPDATE_BACKUP_PATH", &info.env.typst_update_backup_path),
        ("SOURCE_DATE_EPOCH", &info.env.source_date_epoch),
        ("XDG_CACHE_HOME", &info.env.xdg_cache_home),
        ("XDG_DATA_HOME", &info.env.xdg_data_home),
        ("FONTCONFIG_FILE", &info.env.fontconfig_file),
        ("OPENSSL_CONF", &info.env.openssl_conf),
        ("NO_COLOR", &info.env.no_color),
        ("NO_PROXY", &info.env.no_proxy),
        ("HTTP_PROXY", &info.env.http_proxy),
        ("HTTPS_PROXY", &info.env.https_proxy),
        ("ALL_PROXY", &info.env.all_proxy),
    ];

    for (name, value) in &env_vars {
        let padding = " ".repeat(28usize.saturating_sub(name.len()));
        match value {
            Some(v) => println!("  {}{}{}", name, padding, v),
            None => println!("  {}{}<unset>", name, padding),
        }
    }
}
