    println!("  Embedded fonts {}", if info.fonts.embedded { "on" } else { "off" });
    println!();
    println!("Packages");
    println!("  {:<19}{}", "Package path", info.packages.package_path);
    println!("  {:<19}{}", "Package cache path", info.packages.package_cache_path);
    println!();
