                    // where line_no_spaces = ' '.repeat(line_no_str.len())
                    let ln_spaces = " ".repeat(line_no_str.len());
                    let col_spaces = " ".repeat(char_start);
                    let underline = "^".repeat(underline_len);
                    let _ = writeln!(handle, "{} │ {}{}", ln_spaces, col_spaces, underline);
                }

                let _ = writeln!(handle, "");

                for hint in &diag.hints {
                    let _ = writeln!(handle, " = hint: {}", hint.as_str());
                }
                return;
            }
        }
