//! Diagnostic reporting for Typst compile errors

use std::io::{self, Write};
use std::path::{Path, PathBuf};
use typst::diag::{Severity, SourceDiagnostic};
use typst::World;

use crate::args::DiagnosticFormat;
use crate::world::SystemWorld;

pub fn print_diagnostics(
    diagnostics: &[SourceDiagnostic],
    format: &DiagnosticFormat,
    _use_color: bool,
    world: &SystemWorld,
) {
    let stderr = io::stderr();
    let mut handle = stderr.lock();

    for diag in diagnostics {
        match format {
            DiagnosticFormat::Human => {
                print_human_diagnostic(diag, world, &mut handle);
            }
            DiagnosticFormat::Short => {
                print_short_diagnostic(diag, world, &mut handle);
            }
        }
    }
}

fn severity_str(sev: &Severity) -> &'static str {
    match sev {
        Severity::Error => "error",
        Severity::Warning => "warning",
    }
}

fn print_short_diagnostic(
    diag: &SourceDiagnostic,
    world: &SystemWorld,
    handle: &mut impl Write,
) {
    let msg = diag.message.as_str();
    let sev = severity_str(&diag.severity);

    if let Some(id) = diag.span.id() {
        if let Ok(src) = world.source(id) {
            if let Some(range) = src.range(diag.span) {
                let line = src.byte_to_line(range.start).unwrap_or(0) + 1;
                let col = src.byte_to_column(range.start).unwrap_or(0) + 1;
                let path = format_path(id, world);
                let _ = writeln!(handle, "{}:{}:{}: {}: {}", path, line, col, sev, msg);
                for hint in &diag.hints {
                    let _ = writeln!(handle, " = hint: {}", hint.as_str());
                }
                return;
            }
        }
    }

    let _ = writeln!(handle, "{}: {}", sev, msg);
    for hint in &diag.hints {
        let _ = writeln!(handle, " = hint: {}", hint.as_str());
    }
}

fn print_human_diagnostic(
    diag: &SourceDiagnostic,
    world: &SystemWorld,
    handle: &mut impl Write,
) {
    let msg = diag.message.as_str();
    let sev = severity_str(&diag.severity);

    if let Some(id) = diag.span.id() {
        if let Ok(src) = world.source(id) {
            if let Some(range) = src.range(diag.span) {
                let line_start = src.byte_to_line(range.start).unwrap_or(0);
                let line_end = src.byte_to_line(range.end.saturating_sub(1)).unwrap_or(line_start);
                let col_start = src.byte_to_column(range.start).unwrap_or(0);
                let path = format_path(id, world);

                // Calculate the width for line numbers
                let max_line_no = line_end + 1;
                let line_no_width = max_line_no.to_string().len();
                let prefix_spaces = " ".repeat(line_no_width + 1);

                let _ = writeln!(handle, "{}: {}", sev, msg);
                let _ = writeln!(handle, "{}┌─ {}:{}:{}", prefix_spaces, path, line_start + 1, col_start + 1);
                let _ = writeln!(handle, "{}│", prefix_spaces);

                for line_idx in line_start..=line_end {
                    let line_text = src.line(line_idx).unwrap_or("");
                    let line_no = line_idx + 1;
                    let line_no_str = line_no.to_string();

                    let _ = writeln!(handle, "{} │ {}", line_no_str, line_text);

                    let line_byte_start = src.line_to_byte(line_idx).unwrap_or(0);

                    let char_start = if line_idx == line_start {
                        let byte_offset = range.start.saturating_sub(line_byte_start).min(line_text.len());
                        line_text[..byte_offset].chars().count()
                    } else {
                        0
                    };

                    let char_end = if line_idx == line_end {
                        let byte_offset = range.end.saturating_sub(line_byte_start).min(line_text.len());
                        line_text[..byte_offset].chars().count()
                    } else {
                        line_text.chars().count()
                    };

                    let underline_len = char_end.saturating_sub(char_start).max(1);
                    let ln_spaces = " ".repeat(line_no_str.len());
                    let col_spaces = " ".repeat(char_start);
                    let underline = "^".repeat(underline_len);
                    let _ = writeln!(handle, "{} │ {}{}", ln_spaces, col_spaces, underline);
                }

                let _ = writeln!(handle, "");

                for hint in &diag.hints {
                    let _ = writeln!(handle, " = hint: {}", hint.as_str());
                }
                return;
            }
        }
    }

    // No span information
    let _ = writeln!(handle, "{}: {}", sev, msg);
    let _ = writeln!(handle, "");
    for hint in &diag.hints {
        let _ = writeln!(handle, " = hint: {}", hint.as_str());
    }
}

/// Format the path for a FileId for display in diagnostics
fn format_path(id: typst::syntax::FileId, world: &SystemWorld) -> String {
    if let Some(pkg) = id.package() {
        let vpath = id.vpath();
        return format!("{}{}", pkg, vpath.as_rooted_path().display());
    }

    // Local file - construct absolute path then make relative to CWD
    let vpath = id.vpath();
    let abs_path = world.root().join(vpath.as_rooted_path());

    let cwd = std::env::current_dir()
        .unwrap_or_else(|_| world.root().to_path_buf());

    make_relative_from_cwd(&abs_path, &cwd)
}

/// Calculate a relative path from cwd to target
fn make_relative_from_cwd(target: &Path, cwd: &Path) -> String {
    let target_components: Vec<_> = target.components().collect();
    let cwd_components: Vec<_> = cwd.components().collect();

    let common_len = target_components.iter()
        .zip(cwd_components.iter())
        .take_while(|(a, b)| a == b)
        .count();

    let up_count = cwd_components.len() - common_len;

    let mut parts = Vec::new();
    for _ in 0..up_count {
        parts.push("..".to_string());
    }
    for comp in &target_components[common_len..] {
        parts.push(comp.as_os_str().to_string_lossy().to_string());
    }

    if parts.is_empty() {
        ".".to_string()
    } else {
        parts.join("/")
    }
}
