/// Run the init subcommand - initialize a new project from a template
pub fn init_template(args: crate::args::InitArgs) -> i32 {
    use typst_kit::package::{PackageStorage, PackageSpec};
    use std::str::FromStr;

    let package_storage = PackageStorage::new(
        args.package_cache_path.clone(),
        args.package_path.clone(),
        None, // HTTP storage - will be added when network is available
    );

    // Parse the template specifier
    let template_str = args.template.trim_start_matches('@');

    // Try to parse as package spec
    match PackageSpec::from_str(&args.template) {
        Ok(spec) => {
            // Get the target directory
            let target_dir = args.dir.clone()
                .unwrap_or_else(|| std::path::PathBuf::from(spec.name.as_str()));

            // Download/find the package
            match package_storage.prepare_package(&spec, &mut |_| {}) {
                Ok(pkg_path) => {
                    // Create target directory and copy template files
                    if let Err(e) = std::fs::create_dir_all(&target_dir) {
                        eprintln!("error: failed to create directory: {}", e);
                        return 1;
                    }

                    // Copy template files from package
                    // Look for template/ directory in the package
                    let template_path = pkg_path.join("template");
                    let copy_source = if template_path.exists() {
                        template_path
                    } else {
                        pkg_path
                    };

                    if let Err(e) = copy_dir_contents(&copy_source, &target_dir) {
                        eprintln!("error: failed to copy template: {}", e);
                        return 1;
                    }

                    println!("Initialized new project from template '{}' in '{}'", 
                        args.template, target_dir.display());
                    0
                }
                Err(e) => {
                    eprintln!("error: {}", e);
                    1
                }
            }
        }
        Err(e) => {
            eprintln!("error: invalid template specifier '{}': {}", args.template, e);
            1
        }
    }
}

fn copy_dir_contents(src: &std::path::Path, dst: &std::path::Path) -> std::io::Result<()> {
    for entry in std::fs::read_dir(src)? {
        let entry = entry?;
        let entry_path = entry.path();
        let dst_path = dst.join(entry.file_name());

        if entry_path.is_dir() {
            std::fs::create_dir_all(&dst_path)?;
            copy_dir_contents(&entry_path, &dst_path)?;
        } else {
            std::fs::copy(&entry_path, &dst_path)?;
        }
    }
    Ok(())
}
