pub fn init_template(args: crate::args::InitArgs) -> i32 {
    // Create world args for package handling
    let world_args = crate::args::WorldArgs {
        root: None,
        inputs: Vec::new(),
        font_path: Vec::new(),
        ignore_system_fonts: false,
        ignore_embedded_fonts: false,
        package_path: args.package_path.clone(),
        package_cache_path: args.package_cache_path.clone(),
        creation_timestamp: None,
        jobs: None,
        features: Vec::new(),
        diagnostic_format: crate::args::DiagnosticFormat::Human,
    };

    let world = match SystemWorld::new("-", &world_args, None) {
        Ok(w) => w,
        Err(e) => {
            eprintln!("error: {}", e);
            return 1;
        }
    };

    // Try to init using typst-kit package utilities
    // Parse the template spec
    let spec = match args.template.parse::<typst::syntax::PackageSpec>() {
        Ok(s) => s,
        Err(e) => {
            eprintln!("error: invalid template '{}': {}", args.template, e);
            return 1;
        }
