    eprintln!(" = hint: use `typst compile` for one-time compilation");
    1
}'''

new = '''pub fn watch(args: WatchArgs, color: &ColorChoice) -> i32 {
    use std::time::{Duration, Instant};

    let input_path = args.input.clone();
    let output = match &args.output {
        Some(o) => o.clone(),
        None => {
            if input_path == "-" {
                eprintln!("error: please specify an output path when reading from stdin");
                return 1;
            }
            let p = std::path::Path::new(&input_path);
            let stem = p.file_stem().unwrap_or_default();
            format!("{}.pdf", stem.to_string_lossy())
        }
    };

    // Print the watch header
    eprintln!("watching {}", input_path);
    eprintln!("writing to {}", output);
    eprintln!();

    // Do initial compilation
    let start = Instant::now();
    let timestamp = chrono::Local::now().format("%H:%M:%S").to_string();
    eprintln!("[{}] compiling ...", timestamp);

    // Convert WatchArgs to CompileArgs-like struct
    let world_args = args.world.clone();
    let world = match SystemWorld::new(&input_path, &world_args, world_args.creation_timestamp) {
        Ok(w) => w,
        Err(e) => {
            eprintln!("error: {}", e);
            return 1;
        }
    };

    if input_path == "-" {
        let mut stdin_content = String::new();
        let _ = std::io::stdin().read_to_string(&mut stdin_content);
        world.set_stdin_content(stdin_content);
    }

    let format = determine_format(&args.format, &output);

    // Create a CompileArgs-like struct for export
    let compile_args = CompileArgs {
        input: input_path.clone(),
        output: Some(output.clone()),
        format: Some(format.clone()),
        world: world_args,
        pages: args.pages,
        pdf_standard: args.pdf_standard,
        no_pdf_tags: args.no_pdf_tags,
        ppi: args.ppi,
        deps: args.deps,
        deps_format: args.deps_format,
        open: None,
        timings: None,
    };

    let elapsed = start.elapsed();
    let timestamp2 = chrono::Local::now().format("%H:%M:%S").to_string();

    match compile_document(&world) {
        Ok((document, warnings)) => {
            print_diagnostics(&warnings, &compile_args.world.diagnostic_format, color, &world);
            match export_document(&document, &output, &format, &compile_args) {
                Ok(()) => {
                    eprintln!();
                    eprintln!("watching {}", input_path);
                    eprintln!("writing to {}", output);
                    eprintln!();
                    eprintln!("[{}] compiled successfully in {:.2} ms", timestamp2, elapsed.as_secs_f64() * 1000.0);

                    // Wait indefinitely (until killed)
                    loop {
                        std::thread::sleep(Duration::from_secs(1));
                    }
                }
                Err(e) => {
                    eprintln!("error: {}", e);
                    1
                }
            }
        }
        Err(errors) => {
            print_diagnostics(&errors, &compile_args.world.diagnostic_format, color, &world);

            eprintln!();
            eprintln!("watching {}", input_path);
            eprintln!("writing to {}", output);
            eprintln!();
            eprintln!("[{}] compilation failed", timestamp2);

            // Wait indefinitely (until killed)
            loop {
                std::thread::sleep(Duration::from_secs(1));
            }
        }
    }
}'''

