fn write_deps_with_null_output(
    deps_path: &str,
    input_paths: &[String],
    format: &DepsFormat,
) {
    use serde_json;

    let content = match format {
        DepsFormat::Json => {
            let json = serde_json::json!({
                "inputs": input_paths,
